raw_text:
{
  "verifications": [
    {
      "fact_id": "F01",
      "verdict": "VERIFIED",
      "verification_notes": "国連政治・平和構築局の2026年10月9日付発表は、グルンドベルグ特使が「過去数週間でイエメンは全面的な戦闘状態に戻った」と述べたことを掲載しています。タイズ西・南部やラヒジュで戦闘が続き、マリブ、アル・ジャウフ、ハッジャでも戦闘が激化したこと、サウジアラビアの民間・エネルギー施設への攻撃にも言及しています。主張は発表内容と一致します。([dppa.un.org](https://dppa.un.org/en/news/yemen-has-returned-to-full-scale-war-special-envoy-warns?utm_source=openai))"
    },
    {
      "fact_id": "F02",
      "verdict": "VERIFIED",
      "verification_notes": "サウジ国営通信SPA掲載のGACA発表は、10月6日・7日にアブハ空港とキング・ハーリド国際空港が攻撃を受けたとし、アブハではモロッコ・アルジェリア国籍の居住者各1人が死亡、28人が負傷、リヤドではスーダン国籍の居住者1人が死亡、8人が負傷したと記載しています。国籍・人数・日付範囲は一致し、発表は攻撃主体を特定していません。([spa.gov.sa](https://spa.gov.sa/ar/N2695829?utm_source=openai))"
    },
    {
      "fact_id": "F03",
      "verdict": "VERIFIED",
      "verification_notes": "SPA掲載のGACA発表は、10月8日にキング・ハーリド国際空港への攻撃が2件あり、1件は空港施設、もう1件はサウディア機を標的にしたとしています。サウジ人3人の死亡、複数の市民・居住者の負傷、空港運用と航空交通の通常化も記載されています。負傷者数は発表に示されていないため、Ledgerの「負傷者数未公表」という限定も妥当です。([spa.gov.sa](https://www.spa.gov.sa/en/w2697151?utm_source=openai))"
    },
    {
      "fact_id": "F04",
      "verdict": "VERIFIED",
      "verification_notes": "SPA発表を掲載したOANA記事は、10月10日の攻撃について、GACAが10月11日付の続報で死者12人・負傷者309人と発表したと記載しています。後にインド国籍の負傷者が死亡し、死者数が13人になったとの報道もありますが、これは別の更新時点の数字です。Ledgerは12人・309人をGACA続報時点の発表として限定しており、その範囲では正確です。([oananews.org](https://oananews.org/node/713861?utm_source=openai))"
    },
    {
      "fact_id": "F05",
      "verdict": "VERIFIED",
      "verification_notes": "SPA掲載のGACA発表は、10月11日午後にキング・ハーリド国際空港が新たな攻撃を受け、負傷者が出たとしています。損害評価と施設の安全確認が進行中との記載も一致します。発表は負傷者数や攻撃主体を示していません。([spa.gov.sa](https://www.spa.gov.sa/N2698672?utm_source=openai))"
    },
    {
      "fact_id": "F06",
      "verdict": "VERIFIED",
      "verification_notes": "SPA掲載の連合軍報道官の発表は、10月11日、キング・ハーリド国際空港付近で防空部隊が巡航ミサイルを迎撃・破壊したとしています。発表が発射主体や被害の有無を明記していない点もLedgerの記述どおりです。([spa.gov.sa](https://www.spa.gov.sa/en/N2698603?utm_source=openai))"
    },
    {
      "fact_id": "F07",
      "verdict": "VERIFIED",
      "verification_notes": "SPA掲載のGACA発表は、10月11日夜、ダンマームのキング・ファハド国際空港が攻撃を受けたとし、損害評価と安全確認が関係機関と進行中と述べています。当該発表には死傷者数や攻撃主体の記載がありません。([spa.gov.sa](https://www.spa.gov.sa/en/w2698805?utm_source=openai))"
    },
    {
      "fact_id": "F08",
      "verdict": "VERIFIED",
      "verification_notes": "オカーズ紙の記事は、エネルギー省の関係者の説明として、10月13日夜にダーランのサウジアラムコ管理棟が攻撃され、小規模な火災が発生したものの、死者・負傷者はいなかったと報じています。省関係者の説明として帰属を付けている点も適切です。([okaz.com.sa](https://www.okaz.com.sa/local/na/2270709?utm_source=openai))"
    },
    {
      "fact_id": "F09",
      "verdict": "VERIFIED",
      "verification_notes": "SABAの記事は、マリブ県メディア局の報告として、10月15日にマリブ市の住宅地域へ弾道ミサイル9発とその他の飛翔体7発が発射されたと伝えています。独立した現地確認の有無は記事から確認できないため、報告主体を明示するLedgerの限定は妥当です。([sabanew.net](https://sabanew.net/story/en/154079?utm_source=openai))"
    },
    {
      "fact_id": "F10",
      "verdict": "VERIFIED",
      "verification_notes": "アデン首都治安局の発表は、10月16日にフーシ派が発射したミサイル2発がアデン国際空港の敷地内に落下し、初期情報では死者は確認されていないとしています。確認作業が継続中で、負傷者数の記載がない点もLedgerの説明と一致します。([media.aden-gov.net](https://media.aden-gov.net/news/1167?utm_source=openai))"
    },
    {
      "fact_id": "F11",
      "verdict": "VERIFIED",
      "verification_notes": "国連イエメン担当特使の10月11日声明は、サウジアラビアの民間インフラへの継続的な攻撃をアンサール・アッラーによるものとして非難し、10月10日のリヤド空港攻撃についてサウジ当局の情報として死者12人・負傷者300人超を記載しています。また、同週のリヤド・アブハ空港への攻撃による民間人の死傷、地域安全保障への脅威、イエメン和平努力への悪影響という評価も明記しています。([osesgy.unmissions.org](https://osesgy.unmissions.org/en/news/statement-by-un-special-envoy-for-yemen-hans-grundberg-on-latest-attacks-against-saudi?utm_source=openai))"
    }
  ]
}
